const std = @import("std"); const builtin = @import("builtin"); const stor = @import("store");
const tkstorbase = @import("tk-stor-base.zig"); const CF = tkstorbase.CF; const CMDS_SCRI = tkstorbase.CMDS_SCRI; const ChaiStat = tkstorbase.ChaiStat; const DEFA_TMOZ_SECO = tkstorbase.DEFA_TMOZ_SECO; const Load = tkstorbase.Load; const MAXZ_CWDZ = tkstorbase.MAXZ_CWDZ; const MAXZ_FILE = tkstorbase.MAXZ_FILE; const MAXZ_IDSZ = tkstorbase.MAXZ_IDSZ; const MAXZ_LOCK = tkstorbase.MAXZ_LOCK; const MAXZ_PLUS_POOL = tkstorbase.MAXZ_PLUS_POOL; const MAXZ_RETR = tkstorbase.MAXZ_RETR; const MAXZ_RUNZ = tkstorbase.MAXZ_RUNZ; const MAXZ_TMOZ_SECO = tkstorbase.MAXZ_TMOZ_SECO; const NONE_SCHE = tkstorbase.NONE_SCHE; const PLUS_BIGZ = tkstorbase.PLUS_BIGZ; const PLUS_MAXZ = tkstorbase.PLUS_MAXZ; const Reje = tkstorbase.Reje; const STAT_DIRZ = tkstorbase.STAT_DIRZ; const TYPE_LIST = tkstorbase.TYPE_LIST; const Task = tkstorbase.Task; const WINZ_ONLY = tkstorbase.WINZ_ONLY; const autoIdenChec = tkstorbase.autoIdenChec; const chaiChec = tkstorbase.chaiChec; const idenVali = tkstorbase.idenVali; const norm = tkstorbase.norm; const scheNeed = tkstorbase.scheNeed; const taskPath = tkstorbase.taskPath; const typeChec = tkstorbase.typeChec; const winzOnlyChec = tkstorbase.winzOnlyChec;
pub fn vali(tin0: Task) ?[]const u8 { const task = norm(tin0); if (idenVali(task.id)) |whyz| return whyz; if (task.type.len == 0) return "missing type"; if (!typeChec(task.type)) return "unknown type (see 20-folder-layout.md §5)"; if (chaiChec(task)) { if (task.run.len != 0) return "a chai has no run — leave it out"; const idsz = task.ids orelse return "a chai needs ids"; if (idsz.len == 0) return "ids is empty"; if (idsz.len > MAXZ_IDSZ) return "ids too long (max 32 jobs)"; for (idsz, 0..) |memb, indx| { if (idenVali(memb) != null) return "ids: a job id is not valid"; if (std.mem.eql(u8, memb, task.id)) return "ids: a chai cannot list itself"; for (idsz[indx + 1 ..]) |next| if (std.mem.eql(u8, memb, next)) return "ids: the same job is listed twice"; } if (task.plus) |plus| if (plusProb(plus)) |whyz| return whyz; } else { if (task.ids != null) return "ids only applies to type chai"; if (task.plus != null) return "plus only applies to type chai"; if (task.run.len == 0) return "missing run"; } if (task.run.len > MAXZ_RUNZ) return "run too long (max 2048 chars)"; if (task.cwd) |cwdz| if (cwdz.len > MAXZ_CWDZ) return "cwd too long (max 512 chars)"; if (task.lock != null) return "lock moved to aa-conf-main.json lock_list"; if (task.catchup != null) return "catchup is old: use catc 0-9"; if (task.catc) |catc| { if (catc > 9) return "catc must be 0-9"; } if (scheNeed(task.type)) { const sche = task.sche orelse return "this type needs a sche"; if (std.mem.trim(u8, sche, " \t").len == 0) return "sche is empty"; } if (std.mem.eql(u8, task.type, "loop") and !std.mem.eql(u8, task.kind, "shell")) { return "loop requires kind:shell"; } if (!std.mem.eql(u8, task.kind, "shell")) return "unknown kind (only shell for now)"; if (task.guard != null) return "guard is not implemented yet — remove it (planned: 40-improve-plan.md P2.5)"; if (task.npd != null) return "npd is not implemented yet — remove it (planned: 40-improve-plan.md P2.5)"; if (task.admin != null) return "admin is not implemented yet — remove it (planned: 40-improve-plan.md P2.5)"; if (task.tmo) |secs| { if (secs == 0) return "tmo must be at least 1 second"; if (secs > MAXZ_TMOZ_SECO) return "tmo too large (max 24h)"; } if (task.@"try") |retr| { if (retr > MAXZ_RETR) return "try too large (max 10)"; } return null; }
fn plusProb(plus: std.json.Value) ?[]const u8 { if (plus != .array) return "plus must be a list, like [\"y\",\"m\",\"d\",\"h\",[5,10],\"s\"]"; const item = plus.array.items; if (item.len > 6) return "plus: at most 6 positions (years, months, days, hours, mins, secs)"; for (item, 0..) |elem, indx| { switch (elem) { .string => |stri| if (stri.len == 1 and std.ascii.isAlphabetic(stri[0])) {} else if (plusRangBadz(stri, indx)) |whyz| return whyz, .array => |arry| { if (arry.items.len > MAXZ_PLUS_POOL) return "plus: a list has too many values (max 64)"; for (arry.items) |valu| switch (valu) { .integer => |numb| { if (numb < 0) return "plus: list values are whole numbers, 0 or more"; if (numb > PLUS_MAXZ[indx]) return PLUS_BIGZ; }, .string => |stri| if (plusRangBadz(stri, indx)) |whyz| return whyz, else => return "plus: list values are whole numbers, 0 or more", }; }, else => return "plus: each position is one letter (default), a range like \"4..12\", or a list of numbers", } } return null; }
pub fn plusRang(stri: []const u8) ?[2]i64 { const dots = std.mem.indexOf(u8, stri, "..") orelse return null; const lowz = std.fmt.parseInt(i64, stri[0..dots], 10) catch return null; const higz = std.fmt.parseInt(i64, stri[dots + 2 ..], 10) catch return null; if (lowz < 0 or lowz > higz) return null; return .{ lowz, higz }; }
fn plusRangBadz(stri: []const u8, indx: usize) ?[]const u8 { const rang = plusRang(stri) orelse return "plus: a range looks like \"4..12\" (low..high, 0 or more)"; if (rang[1] > PLUS_MAXZ[indx]) return PLUS_BIGZ; return null; }
